# ============================================================
#  PontoFácil — Reorganizar estrutura de pastas
#  Execute na raiz da pasta sistema-ponto no PowerShell
#  PS> Set-ExecutionPolicy -Scope Process Bypass
#  PS> .\reorganizar.ps1
# ============================================================

Write-Host "→ Removendo pastas antigas..." -ForegroundColor Yellow
Remove-Item -Recurse -Force -ErrorAction SilentlyContinue backend
